INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('f9d18115-3ded-425a-b5cc-38935f2510f3','dd43b5de-bd17-4245-8dbf-246de3db401d','instruction','دستورالعمل مراقبت از نوزاد در NICU','INS-H3-002','مصوب کمیته اعتباربخشی بیمارستان نمونه شماره یک','2026-08-25','2026-08-25','2026-08-25','تدوین رویه‌ی استاندارد جهت رعایت الزامات اعتباربخشی','کلیه واحدهای بیمارستان نمونه شماره یک',NULL,NULL,NULL,NULL,'خانم/آقای سرپرستار بخش مراقبت‌های ویژه نوزادان (NICU) بیمارستان شماره یک',NULL,NULL,NULL,'[]',NULL,NULL,'approved',1,'fcc88096-75d7-4430-b494-cc54f4bece33','fcc88096-75d7-4430-b494-cc54f4bece33','2026-08-24 03:43:26','2026-08-24 03:43:26',NULL,0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('78332f8d-abac-40fa-9fea-bfd529f3e79f','dd43b5de-bd17-4245-8dbf-246de3db401d','instruction','دستورالعمل مدیریت پسماند بیمارستانی','INS-H3-003','مصوب کمیته اعتباربخشی بیمارستان نمونه شماره یک','2026-09-17','2026-09-17','2026-09-17','تدوین رویه‌ی استاندارد جهت رعایت الزامات اعتباربخشی','کلیه واحدهای بیمارستان نمونه شماره یک',NULL,NULL,NULL,NULL,'خانم/آقای مسئول بهداشت محیط بیمارستان شماره یک',NULL,NULL,NULL,'[]',NULL,NULL,'approved',1,'fcc88096-75d7-4430-b494-cc54f4bece33','fcc88096-75d7-4430-b494-cc54f4bece33','2026-08-24 03:43:26','2026-08-24 03:43:26',NULL,0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('c9a47b62-3022-47e2-841b-2e627af187cd','dd43b5de-bd17-4245-8dbf-246de3db401d','instruction','دستورالعمل ایمنی و بهداشت شغلی کارکنان','INS-H3-004','مصوب کمیته اعتباربخشی بیمارستان نمونه شماره یک','2026-10-08','2026-10-08','2026-10-08','تدوین رویه‌ی استاندارد جهت رعایت الزامات اعتباربخشی','کلیه واحدهای بیمارستان نمونه شماره یک',NULL,NULL,NULL,NULL,'خانم/آقای مسئول بهداشت حرفه‌ای بیمارستان شماره یک',NULL,NULL,NULL,'[]',NULL,NULL,'approved',1,'fcc88096-75d7-4430-b494-cc54f4bece33','fcc88096-75d7-4430-b494-cc54f4bece33','2026-08-24 03:43:26','2026-08-24 03:43:26',NULL,0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('12f94452-f78e-44de-a083-804c303e12fb','dd43b5de-bd17-4245-8dbf-246de3db401d','instruction','گزارش وقایع ناخواسته','QI-IN-01',NULL,NULL,NULL,NULL,'تعیین روش یکسان شناسایی، ثبت و گزارش وقایع ناخواسته و خطاهای پزشکی بدون ترس از سرزنش، به‌منظور تحلیل ریشه‌ای علل و پیشگیری از تکرار.','کلیه بخش‌های بالینی، پاراکلینیک و پشتیبانی بیمارستان و تمامی رده‌های شغلی.',NULL,NULL,NULL,NULL,'مسئول ایمنی بیمار / مدیر بهبود کیفیت','پایش ماهانه تعداد گزارش‌های ثبت‌شده به تفکیک بخش، نسبت گزارش‌های تحلیل‌شده به کل، و درصد اقدامات اصلاحی بسته‌شده در موعد.',replace('۱. هر فرد شاهد وقوع واقعه ناخواسته، حداکثر ظرف ۲۴ ساعت فرم گزارش را در سامانه ثبت می‌کند.\n۲. گزارش می‌تواند بی‌نام ثبت شود و هویت گزارش‌دهنده محرمانه است.\n۳. کارشناس ایمنی بیمار واقعه را بر اساس شدت پیامد سطح‌بندی می‌کند.\n۴. برای وقایع با شدت بالا، تحلیل ریشه‌ای (RCA) ظرف ۱۰ روز کاری انجام می‌شود.\n۵. اقدامات اصلاحی به واحد مربوطه ابلاغ و اجرای آن پیگیری می‌شود.\n۶. نتایج تجمیعی در کمیته پایش و سنجش کیفیت گزارش می‌شود.','\n',char(10)),NULL,'[]',NULL,NULL,'draft',1,NULL,NULL,'2026-08-24 03:49:54','2026-08-24 03:49:54','ee542d73-6cac-43bf-97aa-a513bf4fa26d',0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('88f0980c-552e-457a-9583-30c7d4205ec2','dd43b5de-bd17-4245-8dbf-246de3db401d','instruction','آگاهی، نگرش مثبت و عملکرد مطلوب کارکنان نسبت به گزارش وقایع ناخواسته','QI-IN-02',NULL,NULL,NULL,NULL,'ارتقای فرهنگ ایمنی بیمار و جایگزینی رویکرد «سرزنش فردی» با «اصلاح فرایند»، تا کارکنان گزارش‌دهی را وظیفه حرفه‌ای بدانند نه ریسک شغلی.','تمامی کارکنان بالینی و غیربالینی بیمارستان.',NULL,NULL,NULL,NULL,'سوپروایزر آموزشی با همکاری مسئول ایمنی بیمار','مقایسه نمره پرسشنامه فرهنگ ایمنی بیمار سال جاری با سال قبل و روند تعداد گزارش‌های داوطلبانه.',replace('۱. برگزاری دوره توجیهی فرهنگ ایمنی بیمار در بدو ورود و بازآموزی سالانه.\n۲. انتشار درس‌آموخته‌های بی‌نام‌شده وقایع در بولتن داخلی.\n۳. سنجش سالانه فرهنگ ایمنی بیمار با پرسشنامه استاندارد HSOPSC.\n۴. تقدیر از بخش‌هایی که بیشترین گزارش‌دهی داوطلبانه را داشته‌اند.','\n',char(10)),NULL,'[]',NULL,NULL,'draft',1,NULL,NULL,'2026-08-24 03:49:54','2026-08-24 03:49:54','ee542d73-6cac-43bf-97aa-a513bf4fa26d',0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('961d8bdb-d962-4a17-a037-d5e4010d053b','dd43b5de-bd17-4245-8dbf-246de3db401d','procedure','مدیریت چک لیست‌های پایش سوپروایزری','QI-PR-01',NULL,NULL,NULL,NULL,'یکسان‌سازی تدوین، اجرا، تحلیل و بازخورد چک‌لیست‌های پایش سوپروایزری در بخش‌ها.','سوپروایزرهای بالینی، آموزشی و کنترل عفونت و کلیه بخش‌های بستری.',NULL,NULL,NULL,NULL,'مدیر خدمات پرستاری','درصد اجرای چک‌لیست‌ها طبق تقویم پایش و روند نمره انطباق بخش‌ها در گزارش فصلی.',replace('۱. تدوین چک‌لیست بر اساس سنجه‌های اعتباربخشی و ابلاغ آن پس از تصویب.\n۲. تعیین دوره پایش (روزانه/هفتگی/ماهانه) برای هر چک‌لیست.\n۳. تکمیل چک‌لیست در محل و ثبت مستندات در سامانه.\n۴. ارائه بازخورد کتبی به سرپرستار بخش حداکثر ظرف ۴۸ ساعت.\n۵. تدوین برنامه بهبود برای موارد با انطباق کمتر از ۸۰ درصد.','\n',char(10)),NULL,'[]',NULL,NULL,'draft',1,NULL,NULL,'2026-08-24 03:49:54','2026-08-24 03:49:54','ee542d73-6cac-43bf-97aa-a513bf4fa26d',0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('9510c435-53db-4691-8cdb-fb1e5ad2b40b','dd43b5de-bd17-4245-8dbf-246de3db401d','procedure','نحوه برخوردهای انضباطی با کارکنان مورد شکایت قرار گرفته','HR-PR-01',NULL,NULL,NULL,NULL,'تعیین فرایند شفاف، عادلانه و مستند رسیدگی به شکایات مطرح‌شده علیه کارکنان و اعمال اقدامات انضباطی متناسب.','کلیه کارکنان رسمی، پیمانی، قراردادی و شرکتی بیمارستان.',NULL,NULL,NULL,NULL,'مدیر منابع انسانی','پایش فصلی تعداد پرونده‌ها، میانگین زمان رسیدگی و نسبت پرونده‌های مختومه در موعد مقرر.',replace('۱. ثبت شکایت در دبیرخانه رسیدگی و تشکیل پرونده.\n۲. اخذ توضیح کتبی از کارمند ظرف ۵ روز کاری.\n۳. بررسی موضوع در کمیته انضباطی با حضور نماینده واحد مربوطه.\n۴. اتخاذ تصمیم متناسب: تذکر شفاهی، تذکر کتبی، توبیخ، ارجاع به مراجع بالادستی.\n۵. ابلاغ کتبی نتیجه به کارمند و ثبت در پرونده پرسنلی.\n۶. حفظ محرمانگی هویت شاکی در تمام مراحل.','\n',char(10)),NULL,'[]',NULL,NULL,'draft',1,NULL,NULL,'2026-08-24 03:49:54','2026-08-24 03:49:54','9575b4d7-0fec-4afe-af21-9012a1dbc177',0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('c8156d41-9f99-4741-901d-952a927b5e99','dd43b5de-bd17-4245-8dbf-246de3db401d','procedure','نگهداری و پشتیبانی داده‌ها و تهیه نسخه پشتیبان','IT-PR-01',NULL,NULL,NULL,NULL,'تضمین در دسترس بودن، صحت و بازیابی‌پذیری داده‌های سامانه اطلاعات بیمارستانی در برابر خرابی سخت‌افزاری، حمله سایبری و خطای انسانی.','کلیه بانک‌های اطلاعاتی HIS، PACS، آزمایشگاه و سامانه‌های اداری.',NULL,NULL,NULL,NULL,'مسئول فناوری اطلاعات','گزارش ماهانه موفقیت پشتیبان‌گیری‌ها و نتیجه آزمون بازیابی فصلی.',replace('۱. تهیه نسخه پشتیبان کامل به‌صورت شبانه و نسخه افزایشی هر ۶ ساعت.\n۲. نگهداری حداقل یک نسخه در محل فیزیکی مجزا از سرور اصلی.\n۳. رمزنگاری نسخه‌های پشتیبان و کنترل دسترسی به آن‌ها.\n۴. آزمون بازیابی (Restore Test) حداقل هر سه ماه یک‌بار و مستندسازی نتیجه.\n۵. ثبت هرگونه خطای پشتیبان‌گیری در دفتر رخداد و رفع آن ظرف ۲۴ ساعت.','\n',char(10)),NULL,'[]',NULL,NULL,'draft',1,NULL,NULL,'2026-08-24 03:49:54','2026-08-24 03:49:54','1221b2b7-301e-4e4c-a487-bf8386e09a3b',0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('ce45f7cc-4939-4cef-bae4-ed91fe80a9f7','dd43b5de-bd17-4245-8dbf-246de3db401d','instruction','راهنمای ثبت صحیح اقدامات و مراقبت‌های پرستاری در پرونده پزشکی بیمار','NR-IN-01',NULL,NULL,NULL,NULL,'یکسان‌سازی نحوه ثبت مراقبت‌های پرستاری به‌گونه‌ای که خوانا، به‌موقع، کامل و قابل استناد قانونی باشد.','کلیه پرستاران و کمک‌پرستاران شاغل در بخش‌های بستری و ویژه.',NULL,NULL,NULL,NULL,'سوپروایزر بالینی','ممیزی ماهانه پرونده‌ها با چک‌لیست ثبت پرستاری روی حداقل ۱۰ پرونده از هر بخش.',replace('۱. ثبت هر اقدام بلافاصله پس از انجام، همراه با تاریخ، ساعت و امضا و مهر نظام پرستاری.\n۲. استفاده از عبارات عینی و پرهیز از اصطلاحات مبهم.\n۳. ممنوعیت لاک‌گرفتن یا پاک‌کردن؛ اصلاح فقط با خط‌زدن تک‌خطی و امضا.\n۴. ثبت ارزیابی اولیه ظرف حداکثر یک ساعت پس از پذیرش بیمار.\n۵. ثبت آموزش به بیمار و پاسخ بیمار در فرم مربوطه.','\n',char(10)),NULL,'[]',NULL,NULL,'draft',1,NULL,NULL,'2026-08-24 03:49:54','2026-08-24 03:49:54','69005b98-76d7-455d-a3af-79d2a2f7f7bf',0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('1f526ae4-94f5-4663-9e34-3640d1e16fe2','dd43b5de-bd17-4245-8dbf-246de3db401d','policy','مشارکت در پیشگیری و ارتقا سلامت در حیطه بیمار','NR-PL-01',NULL,NULL,NULL,NULL,'تعیین رویکرد بیمارستان در مشارکت فعال کادر پرستاری در برنامه‌های پیشگیری، آموزش و ارتقای سلامت بیماران.','تمامی بخش‌های بالینی و درمانگاه‌های تابعه.',NULL,NULL,NULL,NULL,'مدیر خدمات پرستاری','درصد بیماران دارای فرم آموزش تکمیل‌شده و نتایج نظرسنجی رضایت از آموزش.',replace('۱. شناسایی نیازهای آموزشی بیماران در بدو پذیرش.\n۲. ارائه آموزش خودمراقبتی متناسب با بیماری و سطح سواد سلامت بیمار.\n۳. تحویل بسته آموزشی مکتوب هنگام ترخیص.\n۴. پیگیری تلفنی بیماران پرخطر پس از ترخیص.','\n',char(10)),NULL,'[]',NULL,NULL,'draft',1,NULL,NULL,'2026-08-24 03:49:54','2026-08-24 03:49:54','69005b98-76d7-455d-a3af-79d2a2f7f7bf',0,NULL,NULL,0);
INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('26e0aca2-b78f-495c-98c8-9ae8d01e61eb','dd43b5de-bd17-4245-8dbf-246de3db401d','procedure','تشریح نحوه نظارت بر رعایت حقوق گیرندگان خدمت و رعایت اصول اخلاق حرفه‌ای','PR-PR-01',NULL,NULL,NULL,NULL,'تعیین ساز و کار پایش رعایت منشور حقوق بیمار و اصول اخلاق حرفه‌ای در تمامی تعاملات با گیرندگان خدمت.','کلیه کارکنان در تماس با بیمار و همراهان، در همه شیفت‌ها.',NULL,NULL,NULL,NULL,'مسئول دفتر بهبود کیفیت / مددکار اجتماعی','نمره چک‌لیست پایش حقوق گیرنده خدمت، تعداد شکایات مرتبط و میانگین زمان رسیدگی.',replace('۱. نصب منشور حقوق بیمار در معرض دید در تمامی بخش‌ها.\n۲. اخذ رضایت آگاهانه پیش از اقدامات تشخیصی و درمانی تهاجمی.\n۳. رعایت حریم خصوصی بیمار هنگام معاینه و انجام پروسیجر.\n۴. پایش دوره‌ای با چک‌لیست رعایت حقوق گیرنده خدمت در بخش‌ها.\n۵. رسیدگی به شکایات مرتبط و ارائه بازخورد به شاکی.','\n',char(10)),NULL,'[]',NULL,NULL,'draft',1,NULL,NULL,'2026-08-24 03:49:54','2026-08-24 03:49:54','b05a5f0c-7e45-4251-9e1b-aeac5fd018d9',0,NULL,NULL,0);
