INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('14d67ba5-5e15-4a79-b57e-53f7962e4223','dd43b5de-bd17-4245-8dbf-246de3db401d','procedure','روش اجرایی "ارزیابی فرآیند ترخیص، آموزش بیمار و مراقبت پس از خروج"','SOP-LM-27','حکم ابلاغی شماره SOP-LM-27/۱۴۰۵','2026-01-20','2026-06-01','2026-01-15','هدف از تدوین این روش اجرایی، استانداردسازی فرآیند «ارزیابی فرآیند ترخیص، آموزش بیمار و مراقبت پس از خروج»، ارتقای ایمنی و انطباق کامل با سنجه‌های اعتباربخشی ملی وزارت بهداشت می‌باشد.','کلیه بخش‌های درمانی، پاراکلینیک، اداری و پشتیبانی مرتبط در بیمارستان.','کتاب استانداردهای اعتباربخشی ملی بیمارستان‌های ایران (ویرایش پنجم) - محور الف-۱','واژگان و اصطلاحات تخصصی مندرج در کتابچه تعاریف اعتباربخشی و سنجه‌های بالینی.','تجهیزات تخصصی، فرم‌ها و چک‌لیست‌های مدون، سامانه اطلاعات بیمارستانی (HIS) و پرونده پزشکی.','سوپروایزر آموزش سلامت، سرپرستاران بخش‌ها، پرسنل شیفت و مسئولین مربوطه.','مدیر خدمات پرستاری','پایش مستمر بر اساس چک‌لیست‌های دوره‌ای (ماهانه) توسط مدیر خدمات پرستاری و تحلیل در جلسات بهبود کیفیت.',replace('۱. ابلاغ الزامات و برگزاری دوره آموزشی برای پرسنل مرتبط.\n۲. تکمیل دقیق چک‌لیست دوره‌ای به صورت ماهانه توسط سوپروایزر آموزش سلامت.\n۳. ثبت نتایج در سامانه جامع و استخراج مغایرت‌ها.\n۴. تعریف اقدام اصلاحی فوری (CAPA) برای موارد عدم انطباق.\n۵. پایش اثربخشی اقدام اصلاحی و ارائه گزارش به تیم رهبری و مدیریت بیمارستان.','\n',char(10)),'چک‌لیست شماره CHK-LM-27، خط‌مشی مرتبط، کتاب سنجه‌های ملی.','[]',NULL,NULL,'approved',1,NULL,NULL,'2026-10-16 10:44:38','2026-10-16 10:44:38',NULL,0,'2026-12-29',NULL,0);
