INSERT INTO "controlled_documents" ("id","hospital_id","doc_type","title","doc_code","decree_text","issue_date","last_review_date","prepared_date","purpose","scope","legal_references","definitions","resources","related_staff","responsible_person","monitoring_method","work_method","related_documents","distribution_list","attachment_file","attachment_name","status","version_no","created_by","updated_by","created_at","updated_at","section_id","is_example","review_date","source","revision_no") VALUES('e8d70393-7b2c-40bd-93a4-61c31f12f331','dd43b5de-bd17-4245-8dbf-246de3db401d','procedure','روش اجرایی تعبیه خط ورید مرکزی (CV Line) در بیماران بستری','SOP-CLN-21','این روش اجرایی مصوب شورای بهبود کیفیت بیمارستان بوده و رعایت دقیق بندهای آن برای تمامی کارکنان مرتبط الزامی است.','2026-07-05','2026-06-25','2026-01-20','استانداردسازی گام‌به‌گام و خطاناپذیر فرآیند روش اجرایی تعبیه خط ورید مرکزی (CV Line) در بیماران بستری جهت ارتقای ایمنی بیمار و کیفیت مراقبت.','بخش‌های ICU، اتاق‌های عمل و اورژانس','راهنمای اعتباربخشی ملی بیمارستان‌های ایران (ویرایش پنجم)؛ دستورالعمل‌های بالینی وزارت بهداشت.','روش اجرایی مدون: توصیف تفصیلی مراحل عملیاتی، مسئولیت‌ها، ورودی‌ها، خروجی‌ها و نحوه اقدام در شرایط غیراستاندارد.','فرم‌های الکترونیک سامانه HIS، امکانات و تجهیزات تخصصی بخش، پروتکل‌های مدون بالینی.','پزشکان معالج، سرپرستاران، کادر پرستاری و پیراپزشکی مرتبط.','مدیر خدمات بالینی، مترون و دبیر کمیته تخصصی مرتبط','ممیزی دوره‌ای فرآیند توسط دفتر بهبود کیفیت و پایش شاخص‌های عملکردی مربوطه در کمیته‌های بیمارستانی.',replace('۱. بررسی اندیکاسیون بالینی و دستور صریح پزشک معالج در پرونده بیمار.\n۲. آماده‌سازی تجهیزات استاندارد و احراز هویت دو شناسه بیمار.\n۳. اجرای گام‌به‌گام پروتکل بالینی با رعایت حداکثر استانداردهای ایمنی و بهداشت دست.\n۴. مستندسازی دقیق زمان، اقدام انجام‌شده، نام مجری و پاسخ بالینی بیمار در پرونده.\n۵. پایش عوارض احتمالی و ثبت هرگونه واقعه ناخواسته در سامانه گزارش خطا.','\n',char(10)),NULL,'[]',NULL,NULL,'approved',1,NULL,NULL,'2026-10-16 10:44:43','2026-10-16 10:44:43',NULL,0,NULL,NULL,0);
